/* 演示数据：为历史版本补文档内容快照，供文档详情内页的 Markdown 预览 */
function m8DocSnapshotText(d,ver,batch){
  return ['# '+d.name,'','## 概述','本文档为「'+d.name+'」'+ver+' 的内容快照，用于核对文档版本与内容预览。','','## 要点','- 版本：'+ver,'- 切块策略：'+(d.strategy||'—')].join('\\n');
}
function m8DocSnapshotProcessing(d,ver,batch){
  const text=m8DocSnapshotText(d,ver,batch);
  return {file:(d.name||'文档')+'.md',raw:text,sample:false,config:{parent:'按整篇',child:'不切',pLength:'',pOverlap:'',cLength:'',cOverlap:''},blocks:[{kind:'text',text}],chunks:[text],pages:null,originalPages:null};
}
if(!data.m8DocSnapshotsSeeded){
  data.docs.forEach(d=>{
    (d.releases||[]).forEach(r=>{if(!r.processing)r.processing=m8DocSnapshotProcessing(d,r.version,r.batch)});
    if(d.hasDraft&&!d.processing)d.processing=m8DocSnapshotProcessing(d,d.version||'草稿',d.batch);
  });
  data.m8DocSnapshotsSeeded=true;save();
}

/* 批注：测评集无独立版本实体 —— 历史数据中名称/记录尾部残留的「V1.0」等版本号一次性规范化 */
if(!data.m8SetNoVersionMigrated){
  const stripVer=n=>String(n==null?'':n).replace(/\\s*[Vv]\\d+(\\.\\d+)*\\s*$/,'').trim();
  (data.sets||[]).forEach(s=>{const n=stripVer(s.name);if(n)s.name=n});
  (data.runs||[]).forEach(r=>{const n=stripVer(r.set);if(n)r.set=n});
  data.m8SetNoVersionMigrated=true;save();
}

