  if(!targets.length)return m8EvalErr('请至少选择 1 个'+(m8EvalScopeMode==='document'?'文档':'知识库'));
  /* 用户口径：按知识库发起测评时，知识库下所有文档版本必须已关联测评集（提交前二次校验，防绕过禁用态） */
  if(m8EvalScopeMode==='knowledge'){
    const bad=(m8EvalPicked.kbs||[]).map(kbById).filter(k=>k&&!m8KbLinkable(k,m8EvalVerOfKb(k)));
    if(bad.length)return m8EvalErr('知识库「'+bad.map(k=>k.name).join('」「')+'」下仍有文档版本未关联测评集，需全部关联后才可按知识库发起测评');
  }
